  }) => RustLib.instance.api.crateApiBridgeSessionListCaptures(
    that: this,
    dayKey: dayKey,
    cursor: cursor,
    limit: limit,
  );

  /// 分页读某一天的日记版本，契约 `diary.listVersions`。最新在前。
  Future<DiaryVersionPage> listDiaryVersions({
    required String dayKey,
    String? cursor,
    required int limit,
  }) => RustLib.instance.api.crateApiBridgeSessionListDiaryVersions(
    that: this,
    dayKey: dayKey,
    cursor: cursor,
    limit: limit,
  );

  /// 按状态列出任务；不传状态就列全部。
  Future<List<Job>> listJobs({List<JobState>? states, required int limit}) =>
      RustLib.instance.api.crateApiBridgeSessionListJobs(
        that: this,
        states: states,
        limit: limit,
      );

  /// 列出脱敏后的服务配置，契约 `providers.list`。
  ///
  /// **不含密钥**：`credentialRef` 是凭据存储里的引用，只有「配没配」这个信息。
  Future<List<Provider>> listProviders() =>
      RustLib.instance.api.crateApiBridgeSessionListProviders(that: this);

  /// 把 sourceRef + locator 解析成可打开的原件与可用性。
  Future<SourceLocation> locateSource({
