    baseVersionId: baseVersionId,
    candidateVersionIds: candidateVersionIds,
    body: body,
    expectedRevision: expectedRevision,
    operationId: operationId,
  );

  /// 建议的下次唤醒时刻；没有待办时为空。
  Future<DateTime?> nextWakeup() =>
      RustLib.instance.api.crateApiBridgeSessionNextWakeup(that: this);

  /// 申请导入暂存位置。平台层只能往票据指向的文件里写。
  Future<ImportTicket> prepareImport({
    required String captureId,
    required String displayName,
    String? mimeHint,
    PlatformInt64? sizeHint,
    required ImportOrigin origin,
    required String operationId,
  }) => RustLib.instance.api.crateApiBridgeSessionPrepareImport(
    that: this,
    captureId: captureId,
    displayName: displayName,
    mimeHint: mimeHint,
    sizeHint: sizeHint,
    origin: origin,
    operationId: operationId,
  );

  /// 取某个来源**当前修订的父修订**（上一版正文），供界面「看原正文」用。
  ///
  /// 没有上一版时返回空。返回的是修订，不是 diff：差在哪由前端算。
  /// 父修订可能是原件型修订（`text` 为空、`asset_id` 有值），前端要按这个分支
  /// 决定是显示文字还是提供「打开原件」。
  Future<SourceRevision?> previousSourceRevision({required String sourceId}) =>
      RustLib.instance.api.crateApiBridgeSessionPreviousSourceRevision(
        that: this,
        sourceId: sourceId,
      );

  /// 排一条关键词索引重建任务，契约第 4.4 节 `indexes.rebuild`。
  ///
  /// **异步**：只排任务并返回它（`targetIds` 为空表示整库），不做同步重建——同步
  /// 重建会阻塞界面，而队列的退避、补做与依赖闸门已经就绪。`scope` 的编码见契约
  /// 第 4.4 节：`all` 整库，`sources:<id>[,<id>]*` 指定来源（顺序无语义，空列表 /
  /// 非法字符报 `invalid_argument`，不存在的来源报 `not_found`）。
  ///
  /// 幂等：同一个 `(scope, reason, operationId)` 重复调用返回同一条任务；同一个
  /// operationId 换了 scope 或原因报 `idempotency_conflict`。
  Future<Job> rebuildIndexes({
    required String scope,
    required String reason,
    required String operationId,
  }) => RustLib.instance.api.crateApiBridgeSessionRebuildIndexes(
    that: this,
    scope: scope,
    reason: reason,
    operationId: operationId,
  );

  /// 移除服务配置，契约 `providers.remove`。**不删除日记**，也不删除已经生成的回应。
  Future<void> removeProvider({required String providerId}) => RustLib
      .instance
      .api
      .crateApiBridgeSessionRemoveProvider(that: this, providerId: providerId);

  /// 主动请求一次回应，契约 `responses.request`：**只有主动调用才运行**。
  ///
  /// 能力不满足时直接拒绝（`provider_not_configured`，消息里带可执行的下一步），
  /// **不排一条注定失败的任务**；返回的 `jobId` 由驱动在 `run_due_jobs` 里执行。
  Future<ResponseTicket> requestResponse({
    required List<String> captureIds,
    required String requestText,
    String? providerId,
  }) => RustLib.instance.api.crateApiBridgeSessionRequestResponse(
    that: this,
    captureIds: captureIds,
    requestText: requestText,
    providerId: providerId,
  );

  /// 修改某一篇来源的原始文字：新建一个修订，旧修订保留。
  ///
  /// 契约第 4.1 节 `sources.reviseText`。**改完必须再跑一次 `extract_source`**，
  /// 新修订才会进索引——这一步不自动做（提取有自己的失败与重试语义，见
  /// `docs/architecture/m2-修订与检索可见性.md`）。
  Future<SourceRevision> reviseText({
    required String sourceId,
    required String text,
    required PlatformInt64 expectedRevision,
    required String operationId,
  }) => RustLib.instance.api.crateApiBridgeSessionReviseText(
    that: this,
    sourceId: sourceId,
    text: text,
    expectedRevision: expectedRevision,
    operationId: operationId,
  );

  /// **跑一轮到期任务**（驱动），返回本轮摘要：跑了几条、成功/失败各几条、其中多少条是
  /// **补做**（本轮领取时排期已过期）、还有多少到期未跑（被预算/条数截住）、有多少在等
  /// 依赖、下一个唤醒时刻，以及本次的唤醒来源。
  ///
  /// - `budget_ms` 是平台授予的**时间预算**（毫秒），对齐契约 `jobs.runDue` 的
  ///   `budgetMs`；`0` 表示这一轮一条都不跑。预算**只在任务之间判断**：已经在跑的
  ///   任务不打断（核心不做抢占），所以一条任务本身可以比预算还长；
  /// - `trigger` 是唤醒来源（`startup` / `foreground` / `wake` / `manual` …），
  ///   核心如实记进摘要但不改变行为；什么时候调用由平台层决定（#19）；
  /// - 条数上限由这一层夹一个防御性常量 `RUN_DUE_MAX_JOBS`（契约没给这个参数）：
  ///   没跑上的任务留在队列里、如实计入 `dueBacklog`，下一轮接着跑。
  Future<JobRunSummary> runDueJobs({
    required int budgetMs,
    required String trigger,
  }) => RustLib.instance.api.crateApiBridgeSessionRunDueJobs(
    that: this,
    budgetMs: budgetMs,
    trigger: trigger,
  );

  /// 保存人工编辑：新写一条 `user_edit` 版本并让它成为当前，契约 `diary.saveEdit`。
  ///
  /// **不原地改基版**（基版一个字节都不动），旧当前版退成候选。`expectedRevision`
  /// 是这一天的版本数（`candidateVersionIds.length + (currentVersionId == null ? 0 : 1)`），
  /// 不符报 `revision_conflict` 且零改动；同一条 `operationId` 重试返回原版本。
  Future<DiaryVersion> saveDiaryEdit({
    required String baseVersionId,
    required String body,
    required PlatformInt64 expectedRevision,
    required String operationId,
  }) => RustLib.instance.api.crateApiBridgeSessionSaveDiaryEdit(
    that: this,
    baseVersionId: baseVersionId,
    body: body,
    expectedRevision: expectedRevision,
    operationId: operationId,
  );

  /// 保存草稿。只有核心确认落盘后才返回 `durable = true`。
  Future<DraftSaveResult> saveDraft({
    required String captureId,
    required String text,
    required PlatformInt64 expectedRevision,
    required String operationId,
  }) => RustLib.instance.api.crateApiBridgeSessionSaveDraft(
    that: this,
    captureId: captureId,
    text: text,
    expectedRevision: expectedRevision,
    operationId: operationId,
  );

  /// 保存服务配置，契约 `providers.save`。
  ///
  /// `secret` 是明文密钥，**只在这一次调用里经过桥**：核心把它写进密钥托管后只留
  /// 引用（`credentialRef`），数据库、返回值与日志里都没有明文。传 `None` 表示不改
  /// 密钥（沿用配置里的引用；引用留空就是清掉凭据）。
  ///
  /// 协议/端点/模型变了会让上一次的连接测试结论作废——那是对旧配置的验证。
  Future<Provider> saveProvider({required Provider config, String? secret}) =>
      RustLib.instance.api.crateApiBridgeSessionSaveProvider(
        that: this,
        config: config,
        secret: secret,
      );

  /// 翻页；`cursor` 为空表示接着当前进度。游标不属于这个会话报 `cursor_expired`。
  Future<SearchSnapshot> searchNextPage({
    required String sessionId,
    String? cursor,
  }) => RustLib.instance.api.crateApiBridgeSessionSearchNextPage(
    that: this,
    sessionId: sessionId,
    cursor: cursor,
  );

  /// 读当前快照；会话不存在或索引变了报 `search_expired`。
  Future<SearchSnapshot> searchSnapshot({required String sessionId}) => RustLib
      .instance
      .api
      .crateApiBridgeSessionSearchSnapshot(that: this, sessionId: sessionId);

  /// 指定某一天的当前版本，契约 `diary.setCurrent`。
  ///
  /// 只能指向这一天自己的版本（不存在 `not_found`、跨天 `invalid_argument`）；
  /// `expectedRevision` 不符 `revision_conflict`；切到已经是当前的版本是**无操作**，
