    required String versionId,
    required PlatformInt64 expectedRevision,
  }) => RustLib.instance.api.crateApiBridgeSessionSetDiaryCurrent(
    that: this,
    dayKey: dayKey,
    versionId: versionId,
    expectedRevision: expectedRevision,
  );

  /// 发起一次检索，契约第 4.4 节 `search.start`。
  Future<SearchSnapshot> startSearch({
    required SearchRequest request,
    required PlatformInt64 queryRevision,
  }) => RustLib.instance.api.crateApiBridgeSessionStartSearch(
    that: this,
    request: request,
    queryRevision: queryRevision,
  );

  /// 连接测试，契约 `providers.test`。
  ///
  /// **只有显式调用才发网络请求**；`scope` 是用户授权的测试范围，报告里逐项给结论，
  /// 并如实说明「是否真的发生了模型调用」。失败以可区分的错误码抛出
  /// （`provider_not_configured` / `authentication_failed` / `provider_timeout` …），
  /// 消息里写明本次发起了几次真实请求。
  Future<ProviderTestReport> testProvider({
    required String providerId,
    required List<ProviderCapability> scope,
  }) => RustLib.instance.api.crateApiBridgeSessionTestProvider(
    that: this,
    providerId: providerId,
    scope: scope,
  );

  /// 把混合会话从关键词阶段升级到融合阶段（#69）；幂等，重复调用不重复算。
  Future<SearchSnapshot> upgradeSearch({required String sessionId}) => RustLib
      .instance
      .api
      .crateApiBridgeSessionUpgradeSearch(that: this, sessionId: sessionId);
}
